require_once "../config/koneksi.php";$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM transaksi WHERE id_transaksi=?");$s->execute([$id]);$t=$s->fetch();if(!$t)die("Transaksi tidak ditemukan.");$d=$pdo->prepare("SELECT * FROM detail_transaksi WHERE id_transaksi=?");$d->execute([$id]);$detail=$d->fetchAll();function rp($n){return "Rp ".number_format((float)$n,0,',','.');}
?><!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Struk #<?= $id ?></title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="receipt-body"><main class="receipt"><div class="receipt-head"><div class="brand-icon">BR</div><h2>Kasir Bu Rina</h2><p>Terima kasih telah berbelanja</p></div><hr><p>No. Transaksi: <b>#<?= $id ?></b></p><p>Tanggal: <?= date('d/m/Y H:i',strtotime($t['tanggal'])) ?></p><p>Metode: <?= htmlspecialchars(strtoupper($t['metode_bayar'])) ?></p><hr><table><thead><tr><th>Produk</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($detail as $x): ?><tr><td><?= htmlspecialchars($x['nama_produk']) ?><small><?= rp($x['harga']) ?></small></td><td><?= (int)$x['jumlah'] ?></td><td><?= rp($x['subtotal']) ?></td></tr><?php endforeach; ?></tbody></table><hr><div class="receipt-total"><b>TOTAL</b><strong><?= rp($t['total']) ?></strong></div><p class="thanks">Simpan struk ini sebagai bukti transaksi.</p><div class="receipt-actions"><button class="btn btn-primary" onclick="window.print()">Cetak Struk</button><a class="btn btn-soft" href="index.php">Transaksi Baru</a><a class="text-link" href="../index.php">Dashboard</a></div></main></body></html>
